CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE, role public.app_role NOT NULL DEFAULT 'user');
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own role" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE TABLE public.categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, slug text NOT NULL UNIQUE);
GRANT SELECT ON public.categories TO anon, authenticated; GRANT ALL ON public.categories TO service_role; ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read categories" ON public.categories FOR SELECT TO anon, authenticated USING (true);
CREATE TABLE public.collections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text, cover_path text, sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.collections TO anon, authenticated; GRANT ALL ON public.collections TO service_role; ALTER TABLE public.collections ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read collections" ON public.collections FOR SELECT TO anon, authenticated USING (true);
CREATE TABLE public.products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text, cover_path text, banner_path text, price_cents integer NOT NULL DEFAULT 0, previous_price_cents integer, checkout_url text, badge text, category_id uuid REFERENCES public.categories(id), collection_id uuid REFERENCES public.collections(id), featured boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon, authenticated; GRANT ALL ON public.products TO service_role; ALTER TABLE public.products ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read active products" ON public.products FOR SELECT TO anon, authenticated USING (active OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.content_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, title text NOT NULL, description text, topic text, kind text NOT NULL DEFAULT 'guia', cover_path text, pdf_path text, pages integer NOT NULL DEFAULT 0, downloadable boolean NOT NULL DEFAULT false, is_new boolean NOT NULL DEFAULT false, is_bonus boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.content_items TO authenticated; GRANT ALL ON public.content_items TO service_role; ALTER TABLE public.content_items ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.purchases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, product_id uuid NOT NULL REFERENCES public.products(id), external_reference text UNIQUE, status text NOT NULL DEFAULT 'approved', purchased_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.purchases TO authenticated; GRANT ALL ON public.purchases TO service_role; ALTER TABLE public.purchases ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read own purchases" ON public.purchases FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.entitlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, product_id uuid NOT NULL REFERENCES public.products(id), source text NOT NULL DEFAULT 'purchase', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id, product_id));
GRANT SELECT ON public.entitlements TO authenticated; GRANT ALL ON public.entitlements TO service_role; ALTER TABLE public.entitlements ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read own access" ON public.entitlements FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Read entitled content" ON public.content_items FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin') OR EXISTS (SELECT 1 FROM public.entitlements e WHERE e.product_id = content_items.product_id AND e.user_id = auth.uid() AND e.active));
CREATE TABLE public.favorites (user_id uuid NOT NULL, content_id uuid NOT NULL REFERENCES public.content_items(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id, content_id));
GRANT SELECT, INSERT, DELETE ON public.favorites TO authenticated; GRANT ALL ON public.favorites TO service_role; ALTER TABLE public.favorites ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own favorites" ON public.favorites FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.progress (user_id uuid NOT NULL, content_id uuid NOT NULL REFERENCES public.content_items(id) ON DELETE CASCADE, page integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id, content_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.progress TO authenticated; GRANT ALL ON public.progress TO service_role; ALTER TABLE public.progress ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own progress" ON public.progress FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL, body text, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own notifications" ON public.notifications FOR SELECT TO authenticated USING (user_id = auth.uid()); CREATE POLICY "Mark own notifications" ON public.notifications FOR UPDATE TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.banners (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), headline text NOT NULL, body text, image_path text, product_id uuid REFERENCES public.products(id), active boolean NOT NULL DEFAULT true, starts_at timestamptz, ends_at timestamptz);
GRANT SELECT ON public.banners TO authenticated; GRANT ALL ON public.banners TO service_role; ALTER TABLE public.banners ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read live banners" ON public.banners FOR SELECT TO authenticated USING (active AND (starts_at IS NULL OR starts_at <= now()) AND (ends_at IS NULL OR ends_at > now()) OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.updates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, title text NOT NULL, body text, product_id uuid REFERENCES public.products(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.updates TO authenticated; GRANT ALL ON public.updates TO service_role; ALTER TABLE public.updates ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read updates" ON public.updates FOR SELECT TO authenticated USING (true);
CREATE TABLE public.product_recommendations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES public.products(id), audience_product_id uuid REFERENCES public.products(id), excludes_product_id uuid REFERENCES public.products(id), lifetime_only boolean NOT NULL DEFAULT false, sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.product_recommendations TO authenticated; GRANT ALL ON public.product_recommendations TO service_role; ALTER TABLE public.product_recommendations ENABLE ROW LEVEL SECURITY; CREATE POLICY "Read recommendations" ON public.product_recommendations FOR SELECT TO authenticated USING (true);
CREATE INDEX entitlements_user_active_idx ON public.entitlements(user_id, active); CREATE INDEX content_product_idx ON public.content_items(product_id); CREATE INDEX progress_user_idx ON public.progress(user_id);